#include <cstdio>
#include <vector>
#include <queue>
#include <algorithm>

using namespace std;

typedef pair<int, int> pii;
const int inf = 1e9;
const int maxn = 100;

struct edge {
    int to, cost, time;
    edge(int to0, int cost0, int time0) : to(to0), cost(cost0), time(time0) {}
};

vector<edge> G[maxn];
int d[maxn];

void dijkstra(int s, int mode) {
    priority_queue<pii, vector<pii>, greater<pii>> q;
    fill(d, d + maxn, inf);
    d[s] = 0;
    q.push({0, s});

    while (!q.empty()) {
        pii p = q.top(); q.pop();
        int v = p.second;
        if (d[v] < p.first) continue; // Skip if this distance is not the shortest

        for (const auto& e : G[v]) {
            int a = mode == 0 ? e.cost : e.time;
            if (d[e.to] > d[v] + a) {
                d[e.to] = d[v] + a;
                q.push({d[e.to], e.to});
            }
        }
    }
}

signed main() {
    int N, M;
    while (scanf("%d %d", &N, &M), N || M) {
        for (int i = 0; i < M; ++i) G[i].clear();
        for (int i = 0; i < N; ++i) {
            int a, b, cost, time; scanf("%d %d %d %d", &a, &b, &cost, &time); a--; b--;
            G[a].emplace_back(b, cost, time);
            G[b].emplace_back(a, cost, time);
        }
        int K; scanf("%d", &K);
        for (int i = 0; i < K; ++i) {
            int p, q, r; scanf("%d %d %d", &p, &q, &r); p--; q--;
            dijkstra(p, r);
            printf("%d\n", d[q]);
        }
    }
}

